const MAX_ATTEMPTS = 3;
const RETRY_DELAY_MS = 500;
const POLL_MS = 200;
const HEARTBEAT_MS = 1_000;
/** A worker whose heartbeat is older than this is considered dead; its running jobs are requeued. */
const WORKER_DEAD_MS = 5_000;

const workerId = randomUUID();
const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function nowIso(): string {
  return new Date().toISOString();
}

function heartbeat(): void {
  db.prepare(
    `INSERT INTO workers (worker_id, heartbeat_ms) VALUES (?, ?)
     ON CONFLICT (worker_id) DO UPDATE SET heartbeat_ms = excluded.heartbeat_ms`,
  ).run(workerId, Date.now());
}

/**
 * Requeues jobs claimed by workers that have stopped heartbeating (for example after SIGKILL).
 * The interrupted attempt stays counted in `attempts`: it was started, and the next start is a new attempt.
 */
function recoverAbandonedJobs(): void {
  db.prepare(
    `UPDATE jobs
        SET status = 'queued', completed_steps = 0, claimed_by = NULL, updated_at = ?
      WHERE status = 'running'
        AND claimed_by IS NOT NULL
        AND claimed_by != ?
        AND claimed_by NOT IN (SELECT worker_id FROM workers WHERE heartbeat_ms >= ?)`,
  ).run(nowIso(), workerId, Date.now() - WORKER_DEAD_MS);
}

/** Claims the oldest runnable queued job. Returns undefined when there is none. */
function claimNext(): JobRow | undefined {
  return immediateTransaction(db, () => {
    const next = db
      .prepare(`SELECT id FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq ASC LIMIT 1`)
      .get(Date.now()) as { id: string } | undefined;
    if (!next) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed_steps = 0, claimed_by = ?, updated_at = ?
        WHERE id = ? AND status = 'queued'`,
    ).run(workerId, nowIso(), next.id);
    return db.prepare('SELECT * FROM jobs WHERE id = ?').get(next.id) as unknown as JobRow;
  });
